from typing import Annotated

from fastapi import APIRouter, Depends
from fastapi import FastAPI, HTTPException
from pydantic import BaseModel, Field


class ItemIn(BaseModel):
    name: str = Field(min_length=1)
    qty: int = Field(default=0, ge=0)


class ItemOut(ItemIn):
    id: int


class ItemRepo:
    def __init__(self):
        self.rows: dict[int, ItemOut] = {}

    def add(self, item: ItemIn) -> ItemOut:
        new = ItemOut(id=len(self.rows) + 1,
                      **item.model_dump())
        self.rows[new.id] = new
        return new


REPO = ItemRepo()


def get_repo() -> ItemRepo:
    return REPO


RepoDep = Annotated[ItemRepo,
                    Depends(get_repo)]


def get_item(item_id: int,
             repo: RepoDep) -> ItemOut:
    item = repo.rows.get(item_id)
    if item is None:
        raise HTTPException(404, "Немає")
    return item


