from fastapi import FastAPI, HTTPException
from pydantic import BaseModel, Field

app = FastAPI()
STOCK = {1: 5, 2: 0}


class IssueIn(BaseModel):
    qty: int = Field(gt=0)


def get_stock(item_id: int) -> int:
    if item_id not in STOCK:
        raise HTTPException(
            status_code=404,
            detail="Речі не знайдено")
    return STOCK[item_id]


@app.post("/items/{item_id}/issue")
def issue(item_id: int, body: IssueIn):
    left = get_stock(item_id)
    if body.qty > left:
        raise HTTPException(
            status_code=409,
            detail=f"На складі лише {left}")
    STOCK[item_id] = left - body.qty
    return {"left": STOCK[item_id]}

→ POST /items/1/issue {"qty":2}
← 200 {"left":3}
→ POST /items/9/issue {"qty":1}
← 404 {"detail":"Речі не знайдено"}
→ POST /items/1/issue {"qty":10}
← 409 {"detail":"На складі лише 3"}

