from typing import Annotated

from fastapi import Depends, FastAPI
from fastapi import HTTPException
from fastapi.security import HTTPBearer
from fastapi.security import (
    HTTPAuthorizationCredentials as Creds)

app = FastAPI()
bearer = HTTPBearer()
CredDep = Annotated[Creds, Depends(bearer)]
TOKENS = {
    "ivan": {"name": "Іван",
               "role": "комірник"},
    "petro": {"name": "Петро",
                "role": "солдат"},
}
BEARER = {"WWW-Authenticate": "Bearer"}


def current_user(cred: CredDep) -> dict:
    user = TOKENS.get(cred.credentials)
    if user is None:
        raise HTTPException(
            401, "Невірний токен",
            headers=BEARER)
    return user


UserDep = Annotated[dict,
                    Depends(current_user)]


def keeper(user: UserDep) -> dict:
    if user["role"] != "комірник":
        raise HTTPException(
            403, "Лише комірник")
    return user


KeeperDep = Annotated[dict, Depends(keeper)]


@app.get("/me")
def me(user: UserDep):
    return user["name"]


@app.post("/issue")
def issue(user: KeeperDep):
    return f"Видав {user['name']}"

